(function ($) {
    'use strict';
    if (!$ || !$.fn || !$.fn.owlCarousel) return;
    $(function () {
        $('.hero-carousel').owlCarousel({
            loop: true,
            margin: 10,
            nav: true,
            dots: false,
            responsive: {
                0: { items: 1 },
                600: { items: 1 }
            },
            navText: [
                '<span class="lnr lnr-chevron-left" aria-hidden="true"></span>',
                '<span class="lnr lnr-chevron-right" aria-hidden="true"></span>'
            ]
        });
    });
})(window.jQuery);
